    "clinicalCase": "Uma paciente com 19 anos de idade, solteira, busca orientação médica em Unidade Básica de Saúde. Relata que teve duas gestações anteriores, sendo um parto a termo e um aborto, e que tem um filho vivo e saudável de 3 anos de idade. Informa que contraiu infecção pelo HIV há 2 anos e utiliza terapia antirretroviral há 6 meses. Está assintomática e sem sinais clínicos de patologias. Os exames de rotina mostram contagens de LT-CD4+ acima de 500 células/mm e carga viral indetectável. Ela refere início de um relacionamento com parceiro soropositivo de 35 anos de idade há 1 mês. Refere, ainda, que o parceiro tem dois filhos vivos saudáveis e que o casal não deseja ter filhos. Nessa situação, está indicado",
