    "clinicalCase": "Um homem com 24 anos de idade realiza acompanhamento médico regular na Unidade de Saúde da Família (USF) de referência. Possui diagnóstico de HIV há 1 ano, sendo acompanhado em Centro de Saúde de Referência municipal para HIV/AIDS. Hoje, busca atendimento na USF com queixa de perda de peso nos últimos 3 meses, nota que as bermudas estão folgadas. Durante a anamnese, informou que há 3 semanas está com tosse, ocasionalmente apresentando sudorese noturna. Traz consigo exames laboratoriais e de imagem realizados há cerca de 7 dias. Radiografia de tórax com presença de infiltrados e cavidades em lobo superior direito. Prova tuberculínica positiva. Baciloscopia de escarro com presença de raros bacilos álcool-ácido resistente (BAAR). A região onde se encontra a USF apresenta índices elevados de Paracoccidioidomicose, Criptococose e Tuberculose, Toxoplasmose. Diante do quadro apresentado, o novo diagnóstico e os exames complementares adequados para comprová-lo são, respectivamente,",
