        "text": "© explicar que novos exames são desnecessários, indicar atividades físicas, apoio psicológico e retorno, em um continuum de complexidade de tratamento.",
        "isCorrect": true,
        "explanation": "Após avaliação clínica e exames recentes sem evidência de doença cardíaca, metabólica ou tireoidiana, a conduta inicial é acolher e explicar a desnecessidade de novos exames, propor atividade física e apoio psicológico, com retorno e escalonamento terapêutico conforme a evolução."
